#!/usr/bin/env node

/**
 * This script stores web vitals payloads generated by the browser.
 * Pair it with a small client beacon sender in your host app/CDN worker.
 */

import fs from 'node:fs';

const outFile = process.env.WEB_VITALS_LOG || 'web-vitals.ndjson';
const sample = {
  ts: new Date().toISOString(),
  metric: 'LCP',
  value: 0,
  rating: 'good',
  page: '/apps/lerp/',
  source: 'web-vitals',
};

fs.appendFileSync(outFile, `${JSON.stringify(sample)}\n`);
console.log(`web-vitals sample written to ${outFile}`);
